Your expense tracker is below. Add an expense with an amount and a category, and it keeps a running total and a split by category. Entries stay on this page only, so they clear when you close it.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:Segoe UI,sans-serif;margin:0;padding:16px;background:#f7f7f5;color:#222}
  h2{margin:0 0 4px;font-size:18px}
  .sub{color:#666;font-size:13px;margin-bottom:12px}
  .row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}
  input,select,button{font:inherit;padding:8px;border:1px solid #ccc;border-radius:8px;background:#fff}
  input{flex:1;min-width:110px}
  button{background:#2f7d57;color:#fff;border:0;cursor:pointer}
  .total{font-size:24px;font-weight:600;margin:8px 0}
  .bar{height:10px;border-radius:5px;background:#2f7d57;margin:2px 0 8px}
  .cat{font-size:13px;display:flex;justify-content:space-between}
  ul{list-style:none;padding:0;margin:12px 0 0}
  li{display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid #e5e5e0;font-size:14px}
  li small{color:#777;display:block}
  .x{background:none;color:#b3261e;padding:4px 8px;border:0}
  .empty{color:#888;font-size:13px;padding:8px 0}
</style>
</head>
<body>
  <h2>Monthly expenses</h2>
  <div class="sub" id="month"></div>
  <div class="row">
    <input id="desc" placeholder="What was it?">
    <input id="amt" type="number" min="0" placeholder="Amount (₹)">
    <select id="cat">
      <option>Food</option><option>Travel</option><option>Bills</option>
      <option>Shopping</option><option>Health</option><option>Other</option>
    </select>
    <button id="add" type="button">Add</button>
  </div>
  <div>This month's total</div>
  <div class="total" id="total">₹0</div>
  <div id="split"></div>
  <ul id="list"></ul>
<script>
  var items = [];
  var fmt = function(n){ return "₹" + Number(n).toLocaleString("en-IN"); };
  var d = new Date();
  document.getElementById("month").textContent =
    d.toLocaleString("en-IN", {month:"long", year:"numeric"});

  function render(){
    var total = 0, by = {};
    items.forEach(function(i){
      total += i.amt;
      by[i.cat] = (by[i.cat] || 0) + i.amt;
    });
    document.getElementById("total").textContent = fmt(total);

    var split = document.getElementById("split");
    split.innerHTML = "";
    Object.keys(by).sort(function(a,b){ return by[b]-by[a]; }).forEach(function(c){
      var pct = total ? Math.round(by[c] / total * 100) : 0;
      var row = document.createElement("div");
      row.innerHTML = '<div class="cat"><span></span><span></span></div><div class="bar"></div>';
      row.children[0].children[0].textContent = c + " (" + pct + "%)";
      row.children[0].children[1].textContent = fmt(by[c]);
      row.children[1].style.width = pct + "%";
      split.appendChild(row);
    });

    var list = document.getElementById("list");
    list.innerHTML = "";
    if (!items.length){
      list.innerHTML = '<li class="empty">No expenses yet. Add your first one above.</li>';
      return;
    }
    items.slice().reverse().forEach(function(i){
      var li = document.createElement("li");
      var left = document.createElement("div");
      left.textContent = i.desc;
      var small = document.createElement("small");
      small.textContent = i.cat + " · " + i.date;
      left.appendChild(small);
      var right = document.createElement("div");
      right.textContent = fmt(i.amt) + " ";
      var del = document.createElement("button");
      del.className = "x";
      del.type = "button";
      del.textContent = "Remove";
      del.onclick = function(){
        items = items.filter(function(x){ return x.id !== i.id; });
        render();
      };
      right.appendChild(del);
      li.appendChild(left);
      li.appendChild(right);
      list.appendChild(li);
    });
  }

  document.getElementById("add").onclick = function(){
    var desc = document.getElementById("desc");
    var amt = document.getElementById("amt");
    var v = parseFloat(amt.value);
    if (!v || v <= 0) { amt.focus(); return; }
    items.push({
      id: Date.now() + Math.random(),
      desc: desc.value.trim() || "Expense",
      amt: v,
      cat: document.getElementById("cat").value,
      date: new Date().toLocaleDateString("en-IN", {day:"numeric", month:"short"})
    });
    desc.value = "";
    amt.value = "";
    desc.focus();
    render();
  };

  render();
</script>
</body>
</html>
```

