Here's your water tracker. Tap + after each glass, and the ring fills up to your goal of 8.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>
  body{font-family:system-ui,sans-serif;background:#eef7fb;margin:0;padding:24px;text-align:center;color:#12394d}
  h1{font-size:20px;margin:0 0 4px}
  #date{font-size:13px;opacity:.7;margin-bottom:16px}
  .ring{width:150px;height:150px;border-radius:50%;margin:0 auto 12px;display:flex;align-items:center;justify-content:center;background:conic-gradient(#2a9df4 0deg,#cfe6f3 0deg)}
  .inner{width:114px;height:114px;border-radius:50%;background:#eef7fb;display:flex;flex-direction:column;align-items:center;justify-content:center}
  #count{font-size:34px;font-weight:700}
  #of{font-size:12px;opacity:.7}
  #glasses{font-size:26px;letter-spacing:4px;min-height:34px;margin:8px 0}
  button{font-size:20px;border:0;border-radius:12px;padding:10px 22px;margin:4px;background:#2a9df4;color:#fff;cursor:pointer}
  button.alt{background:#fff;color:#12394d;border:1px solid #b9d6e6}
  #msg{margin-top:10px;font-size:14px;min-height:20px}
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="date"></div>
  <div class="ring" id="ring"><div class="inner"><div id="count">0</div><div id="of">of 8 glasses</div></div></div>
  <div id="glasses"></div>
  <div>
    <button class="alt" id="minus">−</button>
    <button id="plus">+ Glass</button>
    <button class="alt" id="reset">Reset</button>
  </div>
  <div id="msg"></div>
<script>
  var GOAL = 8;
  var today = new Date();
  var key = "water-" + today.toISOString().slice(0,10);
  var n = 0;
  try { n = parseInt(localStorage.getItem(key) || "0", 10) || 0; } catch (e) {}
  document.getElementById("date").textContent = today.toDateString();

  function save() { try { localStorage.setItem(key, String(n)); } catch (e) {} }

  function draw() {
    var pct = Math.min(n / GOAL, 1) * 360;
    document.getElementById("ring").style.background =
      "conic-gradient(#2a9df4 " + pct + "deg,#cfe6f3 " + pct + "deg)";
    document.getElementById("count").textContent = n;
    var g = "";
    for (var i = 0; i < Math.max(GOAL, n); i++) g += i < n ? "💧" : "◌";
    document.getElementById("glasses").textContent = g;
    var left = GOAL - n;
    document.getElementById("msg").textContent =
      left > 0 ? left + " more to go" : "Goal reached. Well done! 🎉";
  }

  document.getElementById("plus").onclick = function () { n++; save(); draw(); };
  document.getElementById("minus").onclick = function () { if (n > 0) n--; save(); draw(); };
  document.getElementById("reset").onclick = function () { n = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```
